28: vec3 hash33(vec3 p) {
29:     p = fract(p * vec3(0.1031, 0.1030, 0.0973));
30:     p += dot(p, p.yxz + 33.33);
31:     return fract((p.xxy + p.yxx) * p.zyx);
32: }
33: 
34: vec3 refraction(vec3 ray, vec3 norm, float IOR) {
35:     float r = 1.0 / IOR;
36:     norm = normalize(norm);
37:     ray = normalize(ray);
38: 
39:     float d = dot(norm, ray);
40:     float k = 1.0 - r*r*(1.0-d*d);
41: 
42:     if (k > 0.0) {
43:         return r * ray - (r * d + sqrt(k)) * norm;
44:     }
45: 
46:     return ray - 2.0 * d * norm;
47: }
48: float opDisplacement(vec3 rayPos) {
49:     return sin(rayPos.x * 2.13) * sin(rayPos.y * 4.1) * sin(rayPos.z * 3.1);
50: }
51: vec3 opTwist(vec3 p, float k) {
52:     float c = cos(k*p.y);
53:     float s = sin(k*p.y);
54:     return vec3( mat2(c, -s, s, c) * p.xz, p.y);
55: }
56: 
57: float sdSphere(vec3 rayPos, vec3 spherePos, float r) {
58:     return length(rayPos - spherePos) - r;
59: }
60: float sdBox( vec3 rayPos, vec3 b ) {
61:     vec3 q = abs(rayPos) - b;
62:     return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
63: }
64: float sdCappedCylinder( vec3 p, float r, float h ) {
65:     vec2 d = abs(vec2(length(p.xy), p.z)) - vec2(r,h);
66:     return min(max(d.x,d.y),0.0) + length(max(d,0.0));
67: }
68: vec3 rotate(vec3 p, vec3 r) {
69:     vec3 s = sin(r);
70:     vec3 c = cos(r);
71:     // vec3 s = vec3(sin(r.x), sin(r.y), sin(r.z));
72:     // vec3 c = vec3(cos(r.x), cos(r.y), cos(r.z));
73: 
74:     return p * mat3(
75:         1., 0., 0.,
76:         0., c.x, -s.x,
77:         0., s.x, c.x
78:     ) * mat3(
79:         c.y, 0., s.y,
80:         0., 1., 0.,
81:         -s.y, 0., c.y
82:     ) * mat3(
83:         c.z, -s.z, 0.,
84:         s.z, c.z, 0.,
85:         0., 0., 1.
86:     );
87: }
